package com.bn.atmcontratos.controller;
import com.bn.atmcontratos.dto.*; import com.bn.atmcontratos.model.entity.*; import com.bn.atmcontratos.model.enums.*; import com.bn.atmcontratos.repository.*; import com.bn.atmcontratos.security.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController{
 private final AuthenticationManager auth; private final JwtService jwt; private final UsuarioRepository users; private final PasswordEncoder encoder;
 @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){var a=auth.authenticate(new UsernamePasswordAuthenticationToken(r.getUsername(),r.getPassword())); Usuario u=(Usuario)a.getPrincipal(); return new AuthResponse(jwt.generate(u,Map.of("rol",u.getRol().name())),u.getUsername(),u.getNombreCompleto(),u.getRol());}
 @PostMapping("/register") public AuthResponse reg(@RequestBody RegisterRequest r){if(users.existsByUsername(r.getUsername()))throw new RuntimeException("Usuario ya existe"); Usuario u=users.save(Usuario.builder().username(r.getUsername()).password(encoder.encode(r.getPassword())).nombreCompleto(r.getNombreCompleto()).rol(r.getRol()==null?RolNombre.USUARIO:r.getRol()).build()); return new AuthResponse(jwt.generate(u,Map.of("rol",u.getRol().name())),u.getUsername(),u.getNombreCompleto(),u.getRol());}
}
